css:
#dyn-mosaic-theme[data-theme="tmpl-card-decks"]  {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12%;
  padding: 8% 6% 16%;
  overflow: visible;
}
#dyn-mosaic-theme[data-theme="tmpl-card-decks"] .dyn-pile  {
  position: relative;
  width: min(26cqw, 360px);
  aspect-ratio: 2 / 3;
  flex: 0 0 auto;
  overflow: visible;
}
#dyn-mosaic-theme[data-theme="tmpl-card-decks"] .dyn-card  {
  position: absolute;
  inset: 0;
  transform-origin: 50% 50%;
  transition: transform 0.55s cubic-bezier(0.22, 0.8, 0.2, 1);
}
#dyn-mosaic-theme[data-theme="tmpl-card-decks"] .dyn-card.is-dealing,
#dyn-mosaic-theme[data-theme="tmpl-card-decks"] .dyn-card.is-face  {
  transition: none;
}
#dyn-mosaic-theme[data-theme="tmpl-card-decks"]  {
  background: radial-gradient(70% 50% at 50% 40%, #2a1c14, #0b0b0d 72%);
}
#dyn-mosaic-theme[data-theme="tmpl-card-decks"].dyn-layout-row .dyn-custom-cards  {
  justify-content: center;
  gap: 11%;
  padding: 8% 6% 16%;
  align-items: center;
}
#dyn-mosaic-theme[data-theme="tmpl-card-decks"] .dyn-card  {
  position: relative;
  flex: 0 0 16%;
  width: 16%;
  height: 58%;
  border-radius: 14px;
  box-shadow: 0 18px 40px rgba(0,0,0,.45);
}
#dyn-mosaic-theme[data-theme="tmpl-card-decks"] .dyn-card:nth-child(3n+1)  {
   transform: rotate(-9deg) translate(8px, 10px);
   z-index: 1;
   }
#dyn-mosaic-theme[data-theme="tmpl-card-decks"] .dyn-card:nth-child(3n+2)  {
   transform: rotate(2deg) translate(-2px, -4px);
   z-index: 2;
   }
#dyn-mosaic-theme[data-theme="tmpl-card-decks"] .dyn-card:nth-child(3n)  {
   transform: rotate(8deg) translate(-10px, 6px);
   z-index: 3;
   }
